def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids for immediate pressure.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Base bid tuned to observed winning band (~77-87).
    # If supply is tight (closer to 15), bid slightly more.
    tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1-ish
    tightness = max(0.0, min(1.0, tightness))

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone already pushed very high, I must respond.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * (0.85 + 0.05 * tightness)
        else:
            # Otherwise, bid just above the observed high to secure water.
            target = max(DAILY_SALARY * 0.55, highest_prev_bid + 2.0 + 6.0 * tightness)
    else:
        target = DAILY_SALARY * (0.55 + 0.2 * tightness)

    # Survival urgency adjustments.
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 3:
        target = max(target, DAILY_SALARY * 0.75)

    # If I've already gone multiple days without water, increase.
    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * (0.8 + 0.1 * tightness))

    # Ensure we don't overbid beyond budget.
    if budget <= 0:
        return 0.0

    # Cap target to budget while keeping a slight reserve.
    reserve = 0.05 * budget
    bid = min(budget - reserve, target)

    # Safety: if reserve makes bid negative, just spend what we can.
    if bid < 0:
        bid = min(budget, target)

    return float(max(0.0, bid))

