def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_agents = len(alive_opponents) + 1

    remaining_days = EPISODE_DAYS - day_context['day']

    base_bid_multiplier = 0.6

    if my_status['hp'] <= 2:
        base_bid_multiplier = 0.95
    elif my_status['hp'] <= 4:
        base_bid_multiplier = 0.85
    elif my_status['hp'] >= 8 and my_status['budget'] > DAILY_SALARY * 5:
        base_bid_multiplier = 0.5

    if my_status['no_water_days'] > 0:
        base_bid_multiplier = max(base_bid_multiplier, 0.98)

    if remaining_days <= 2:
        base_bid_multiplier = max(base_bid_multiplier, 0.9)
    elif remaining_days <= 4:
        base_bid_multiplier = max(base_bid_multiplier, 0.75)

    my_calculated_bid = DAILY_SALARY * base_bid_multiplier

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        num_full_water_slots = int(day_context['supply'] // WATER_REQ)
        is_supply_tight = num_full_water_slots < num_alive_agents

        if is_supply_tight:
            if my_status['hp'] <= 4 or remaining_days <= 3 or my_status['no_water_days'] > 0:
                my_calculated_bid = max(my_calculated_bid, highest_prev_bid + 5)
            else:
                my_calculated_bid = max(my_calculated_bid, highest_prev_bid + 1)
        else:
            if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
                 my_calculated_bid = max(my_calculated_bid, highest_prev_bid + 1)
            else:
                my_calculated_bid = min(my_calculated_bid, highest_prev_bid * 0.95)
                my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.4)

    final_bid = min(my_status['budget'], my_calculated_bid)
    final_bid = max(1.0, final_bid)

    return final_bid
